 for dx,dy,a,b,di in [(0,-1,(2*x-1,2*y-1),(2*x+1,2*y-1),0),(1,0,(2*x+1,2*y-1),(2*x+1,2*y+1),1),(0,1,(2*x+1,2*y+1),(2*x-1,2*y+1),2),(-1,0,(2*x-1,2*y+1),(2*x-1,2*y-1),3)]:
  if not SAFE[y+dy,x+dx]: edges.setdefault(a,[]).append((b,di,(int(x),int(y))))
loops=[]
while edges:
 start=next(iter(edges));cur=start;di=0;pts=[]
 while True:
  opts=edges[cur]; k=min(range(len(opts)),key=lambda k:{1:0,0:1,3:2,2:3}[(opts[k][1]-di)%4])
  nxt,di,p=opts.pop(k)
  if not opts:del edges[cur]
