 loop=loop[j:-1]+loop[:j+1]
 path.extend(route(path[-1],loop[0])[1:]);path.extend(loop[1:])
np.save('/app/output/main_path.npy',np.array(path))
print('contours',list(map(len,loops)),'total length_mm',np.linalg.norm(np.diff(path,axis=0),axis=1).sum()*.22186)
